{"path": "app/assets/stylesheets/application.css", "content": ":root {
  --bg: #f5f7fa;
  --card: #ffffff;
  --text: #1f2933;
  --muted: #6b7280;
  --border: #e4e7eb;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.dashboard {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

.dashboard__header h1 {
  margin: 0 0 4px;
  font-size: 28px;
}

.dashboard__subtitle {
  margin: 0 0 24px;
  color: var(--muted);
}

.filter {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 24px;
}

#filter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
}

.filter__field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.filter__field label {
  font-size: 13px;
  color: var(--muted);
}

.filter__field input {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 14px;
}

.filter__actions {
  display: flex;
  gap: 12px;
  align-items: center;
}

.filter__actions input[type="submit"] {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 9px 18px;
  font-size: 14px;
  cursor: pointer;
}

.filter__clear {
  color: var(--muted);
  font-size: 14px;
  text-decoration: none;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 32px;
}

.metric {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.metric__label {
  font-size: 13px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.metric__value {
  font-size: 24px;
  font-weight: 700;
}

.chart-section,
.table-section {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px;
  margin-bottom: 24px;
}

.chart-section h2,
.table-section h2 {
  margin: 0 0 16px;
  font-size: 18px;
}

.chart {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chart-bar {
  display: grid;
  grid-template-columns: 140px 1fr 120px;
  align-items: center;
  gap: 12px;
}

.chart-bar__label {
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chart-bar__track {
  display: block;
  background: var(--accent-soft);
  border-radius: 6px;
  height: 22px;
  overflow: hidden;
}

.chart-bar__fill {
  display: block;
  height: 100%;
  background: var(--accent);
  border-radius: 6px;
  min-width: 2px;
}

.chart-bar__value {
  font-size: 14px;
  text-align: right;
  color: var(--muted);
}

.orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.orders-table th,
.orders-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.orders-table thead th {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.orders-table__amount {
  text-align: right;
}

.orders-table tfoot th {
  border-bottom: none;
  border-top: 2px solid var(--border);
}

.empty-state {
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 10px;
  padding: 40px 20px;
  text-align: center;
}

.empty-state h2 {
  margin: 0 0 8px;
  font-size: 18px;
}

.empty-state p {
  margin: 0;
  color: var(--muted);
}
"}

